function toTaskResource(task, projectId2, parentId, position) {
  return {
    id: task.id,
    projectId: projectId2,
    parentId,
    position,
    path: task.filePath ?? "",
    title: task.title,
    description: task.description,
    type: task.type,
    status: task.status,
    priority: task.priority,
    start: task.start,
    due: task.due,
    completed: task.completed,
    progress: task.progress,
    assignees: [...task.assignees],
    tags: [...task.tags],
    dependencies: [...task.dependencies],
    recurrence: task.recurrence ? { ...task.recurrence } : null,
    timeEstimate: task.timeEstimate ?? null,
    timeLogs: (task.timeLogs ?? []).map((log) => ({ ...log })),
    customFields: { ...task.customFields },
    archived: task.archived === true,
    createdAt: task.createdAt,
    updatedAt: task.updatedAt
  };
}
function taskResources(project, projectId2, includeArchived) {
  const out = [];
  const walk = (tasks, parentId) => {
    tasks.forEach((task, position) => {
      if (task.archived && false) ;
      out.push(toTaskResource(task, projectId2, parentId, position));
      walk(task.subtasks, task.id);
    });
  };
  walk(project.tasks, null);
  return out;
}
function toProjectResource(project, config, summary) {
  return {
    ...summary,
    description: project.description,
    teamMembers: [...project.teamMembers],
    customFields: config.customFields.map((field) => ({ ...field })),
    statuses: config.statuses.map((status) => ({ ...status })),
    priorities: config.priorities.map((priority) => ({ ...priority })),
    createdAt: project.createdAt,
    updatedAt: project.updatedAt
  };
}

